<script setup>
import { computed } from 'vue'
import { ArrowUpRight, FileCheck2, Clock3, Wallet, Building2, ArrowRight, ShieldCheck, Users, CreditCard, Landmark, ArrowLeftRight, Zap, Contact, Smartphone } from 'lucide-vue-next'
import { money, label, date } from '../services/api'
import StatusBadge from '../components/StatusBadge.vue'
const props = defineProps({ data: Object, clients: Array, can: Function })
defineEmits(['navigate', 'action', 'open'])
const maximum = computed(() => Math.max(1, ...(props.data?.por_estado || []).map(x => x.cantidad)))
// Registry tiles: totals Gestiones administers as the core of the three systems.
const registry = computed(() => { const g = props.data?.global; if (!g) return []; return [
  { key:'clientes', icon:Users, tone:'blue', title:'Clientes', value:g.clientes, detail:`${g.clientes_con_app} con acceso a Banca Virtual` },
  { key:'clientes', icon:Smartphone, tone:'teal', title:'Sesiones activas en la app', value:g.sesiones_app_activas, detail:'Credenciales administradas en Gestiones' },
  { key:'cuentas', icon:Wallet, tone:'teal', title:'Cuentas', value:g.cuentas_ahorro + g.cuentas_monetarias, detail:`${g.cuentas_ahorro} de ahorro · ${g.cuentas_monetarias} monetarias${g.cuentas_bloqueadas ? ` · ${g.cuentas_bloqueadas} bloqueadas` : ''}` },
  { key:'cuentas', icon:Landmark, tone:'blue', title:'Saldos de clientes', value:money(g.saldo_ahorro_centavos + g.saldo_monetario_centavos), detail:`Ahorro ${money(g.saldo_ahorro_centavos)} · Monetario ${money(g.saldo_monetario_centavos)}` },
  { key:'tarjetas', icon:CreditCard, tone:'violet', title:'Tarjetas', value:g.tarjetas_credito + g.tarjetas_debito, detail:`Límite otorgado ${money(g.limite_credito_centavos)} · Deuda ${money(g.deuda_tarjetas_centavos)}` },
  { key:'creditos', icon:FileCheck2, tone:'amber', title:'Créditos autorizados', value:g.creditos_autorizados, detail:`Monto autorizado ${money(g.creditos_autorizados_centavos)}` },
  { key:'movimientos', icon:ArrowLeftRight, tone:'teal', title:'Movimientos de hoy', value:g.movimientos_hoy, detail:`Volumen ${money(g.volumen_hoy_centavos)}` },
  { key:'movimientos', icon:Zap, tone:'amber', title:'Pagos de servicios', value:g.pagos_servicios, detail:`Total pagado ${money(g.pagos_servicios_centavos)}` },
  { key:'colaboradores', icon:Contact, tone:'violet', title:'Banca corporativa', value:g.empresas, detail:`${g.colaboradores} colaboradores en planilla` },
] })
const customer = id => props.clients.find(x => (x.id || x._id) === id)?.nombre || 'Cliente registrado'
</script>
<template>
  <div v-if="data" class="dashboard">
    <section class="overview-intro"><div><p class="eyebrow">UNA VISTA DE TODA LA OPERACIÓN</p><h2>Todo listo para seguir avanzando.</h2><p>Atiende las gestiones que los clientes envían desde Banca Virtual.</p></div><span class="inbox-note">Las gestiones llegan desde Banca Virtual</span></section>
    <section class="metrics">
      <article class="metric"><div class="metric-top"><span>Gestiones registradas</span><span class="metric-icon blue"><FileCheck2 :size="20"/></span></div><strong>{{ data.solicitudes }}</strong><small>Recibidas desde Banca Virtual <ArrowUpRight :size="14"/></small></article>
      <article class="metric"><div class="metric-top"><span>Por aprobar</span><span class="metric-icon amber"><Clock3 :size="20"/></span></div><strong>{{ data.pendientes }}<span class="metric-suffix">gestiones</span></strong><small>En evaluación, esperando tu aprobación</small></article>
      <article class="metric"><div class="metric-top"><span>Control centralizado</span><span class="metric-icon teal"><Landmark :size="20"/></span></div><strong class="amount">{{ money(data.saldo_centavos) }}</strong><small>Saldo total de {{ data.global?.clientes ?? 0 }} clientes · {{ data.cuentas }} cuentas · {{ (data.global?.tarjetas_credito ?? 0) + (data.global?.tarjetas_debito ?? 0) }} tarjetas</small></article>
      <article class="metric"><div class="metric-top"><span>Planillas por autorizar</span><span class="metric-icon violet"><Building2 :size="20"/></span></div><strong>{{ data.planillas_pendientes }}</strong><small>Requieren una segunda aprobación</small></article>
    </section>
    <div class="dashboard-grid"><section class="panel recent-panel"><div class="panel-heading"><div><h3>Gestiones recientes</h3><p>Últimas gestiones recibidas</p></div><button class="text-button" @click="$emit('navigate', 'solicitudes')">Ver todas <ArrowRight :size="16"/></button></div><div class="table-wrap"><table><thead><tr><th>CLIENTE / GESTIÓN</th><th>PRODUCTO</th><th>ESTADO</th><th></th></tr></thead><tbody><tr v-for="item in data.recientes" :key="item.id" @click="$emit('open', item)"><td><div class="person-cell"><span class="avatar">{{ customer(item.cliente_id).slice(0, 2).toUpperCase() }}</span><span><b>{{ customer(item.cliente_id) }}</b><small>{{ item.folio }}</small></span></div></td><td>{{ label(item.producto) }}</td><td><StatusBadge :value="item.estado"/></td><td><button class="icon-button" aria-label="Ver solicitud" @click.stop="$emit('open', item)"><ArrowUpRight :size="18"/></button></td></tr><tr v-if="!data.recientes.length"><td colspan="4" class="empty-inline">Aún no hay gestiones. Llegarán cuando los clientes las envíen desde Banca Virtual.</td></tr></tbody></table></div></section>
    <section class="panel distribution"><div class="panel-heading"><div><h3>Flujo de gestiones</h3><p>Distribución por etapa</p></div><span class="small-tag">RESUMEN</span></div><div class="bars"><div v-for="item in data.por_estado" :key="item.estado"><div class="bar-label"><span>{{ label(item.estado) }}</span><b>{{ item.cantidad }}</b></div><div class="bar-track"><span :class="item.estado" :style="{width: `${item.cantidad / maximum * 100}%`}"></span></div></div></div><div class="distribution-footer"><ShieldCheck :size="18"/><span><b>{{ data.emitidas }} gestiones emitidas</b><small>Con historial completo de aprobación</small></span></div></section></div>
    <section class="registry-section"><div><h3>Registro global del banco</h3><p>Todo lo que CP Gestiones centraliza como sistema principal. Haz clic para ver el detalle.</p></div><div class="registry-grid"><button v-for="tile in registry" :key="tile.title" class="registry-tile" @click="$emit('navigate', tile.key)"><span class="metric-icon" :class="tile.tone"><component :is="tile.icon" :size="18"/></span><span><small>{{ tile.title }}</small><b>{{ tile.value }}</b><em>{{ tile.detail }}</em></span></button></div></section>
    <section class="quick-section"><div><h3>Operaciones frecuentes</h3><p>Continúa con una gestión del día a día.</p></div><div class="quick-actions"><button v-if="can('cuentas.write')" @click="$emit('action', 'cuentas')"><span class="metric-icon blue"><Wallet :size="20"/></span><span><b>Abrir una cuenta</b><small>Ahorro o monetaria</small></span><ArrowUpRight :size="19"/></button><button v-if="can('dinero.write')" @click="$emit('action', 'transferencia')"><span class="metric-icon teal"><ArrowRight :size="20"/></span><span><b>Transferir fondos</b><small>Entre cuentas del banco</small></span><ArrowUpRight :size="19"/></button><button v-if="can('planillas.write')" @click="$emit('action', 'planillas')"><span class="metric-icon violet"><Building2 :size="20"/></span><span><b>Cargar una planilla</b><small>Pagos con doble autorización</small></span><ArrowUpRight :size="19"/></button></div></section>
  </div>
</template>
